#include <vector>
#include <string>
#include <sstream>

using namespace std;

class Solution {
public:
    vector<string> printVertically(string s) {
        istringstream iss(s);
        vector<string> words, res;
        string word;
        int maxLen = 0;
        while (iss >> word) {
            words.push_back(word);
            maxLen = max(maxLen, (int)word.size());
        }

        for (int i = 0; i < maxLen; ++i) {
            string line;
            for (string& w : words)
                line += i < w.size() ? w[i] : ' ';
            while (!line.empty() && line.back() == ' ') line.pop_back();
            res.push_back(line);
        }
        return res;
    }
};
